package com.registration.servlet;
import com.registration.dao.StudentDAO;import com.registration.model.Student;import javax.servlet.http.*;import javax.servlet.*;import java.io.*;import java.sql.SQLException;import java.util.*;
public class StudentListServlet extends HttpServlet{private static final long serialVersionUID=1L;private final StudentDAO dao=new StudentDAO();protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{r.setContentType("text/html;charset=UTF-8");try{render(r,dao.getAllStudents(),null);}catch(SQLException e){render(r,null,"Unable to retrieve students. Check the MySQL connection.");}}private void render(HttpServletResponse r,List<Student>a,String e)throws IOException{PrintWriter o=r.getWriter();o.print("<!DOCTYPE html><html><head><meta charset='UTF-8'><title>View Students</title><link rel='stylesheet' href='css/style.css'></head><body class='content-page'><main class='page-shell'><section class='hero'><div><div class='eyebrow'>DATABASE RECORDS</div><h1>Registered Students</h1><p>Loaded directly from MySQL through JDBC.</p></div><div class='hero-mark'>DB</div></section><section class='card'>");if(e!=null)o.print("<div class='status-card status-error'><span class='status-badge'>ERROR</span><h1>Could not load records</h1><p>"+h(e)+"</p></div>");else if(a.isEmpty())o.print("<div class='empty-state'>No students registered yet.</div>");else{o.print("<div class='table-wrap'><table class='student-table'><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Gender</th><th>Course</th><th>DOB</th><th>Address</th></tr></thead><tbody>");for(Student s:a)o.print("<tr><td>"+s.getId()+"</td><td>"+h(s.getFullName())+"</td><td>"+h(s.getEmail())+"</td><td>"+h(s.getPhone())+"</td><td>"+h(s.getGender())+"</td><td>"+h(s.getCourse())+"</td><td>"+s.getDateOfBirth()+"</td><td>"+h(s.getAddress())+"</td></tr>");o.print("</tbody></table></div>");}o.print("</section></main></body></html>");}private String h(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}}